export interface Account {
  firstName: string;
  lastName: string;
  secret: string;
}

export interface AccountUpdate {
  firstName: string;
  lastName: string;
}

export interface UpdateResult {
  ok: boolean;
  message: string;
}

export class AccountManager {
  private account: Account;

  public constructor(account: Account) {
    const firstName = account.firstName.trim();
    const lastName = account.lastName.trim();
    if (firstName.length === 0 || lastName.length === 0 || account.secret.trim().length === 0) {
      throw new TypeError("names and secret must not be empty");
    }
    this.account = { ...account, firstName, lastName };
  }

  public snapshot(): Account {
    return { ...this.account };
  }

  public rename(firstName: string, lastName: string): UpdateResult {
    const first = firstName.trim();
    const last = lastName.trim();
    if (first.length === 0 || last.length === 0) {
      return { ok: false, message: "Both names are required" };
    }
    this.account.firstName = first;
    this.account.lastName = last;
    return { ok: true, message: "Name updated" };
  }

  public changeSecret(oldSecret: string, newSecret: string, repeatedSecret: string): UpdateResult {
    if (oldSecret !== this.account.secret) {
      return { ok: false, message: "Current secret is incorrect" };
    }
    if (newSecret.trim().length === 0) {
      return { ok: false, message: "New secret is required" };
    }
    if (oldSecret !== repeatedSecret) {
      return { ok: false, message: "New secrets do not match" };
    }
    this.account.secret = newSecret;
    return { ok: true, message: "Secret updated" };
  }
}

