import { AccountManager } from "./solution";
import type { Account, AccountUpdate, UpdateResult } from "./solution";

function assert(condition: boolean, message: string): void {
  if (!condition) throw new Error(message);
}

function equal(actual: unknown, expected: unknown, message: string): void {
  const a = JSON.stringify(actual);
  const e = JSON.stringify(expected);
  if (a !== e) throw new Error(`${message}: expected ${e}, received ${a}`);
}

function throwsType(action: () => void, message: string): void {
  let caught: unknown;
  try { action(); } catch (error: unknown) { caught = error; }
  if (!(caught instanceof TypeError)) throw new Error(`${message}: expected TypeError`);
}

const source: Account = { firstName: " Ada ", lastName: " Lovelace ", secret: "  secret value  " };
const manager = new AccountManager(source);
source.firstName = "Caller mutation";
source.lastName = "Caller mutation";
source.secret = "Caller mutation";
equal(manager.snapshot(), { firstName: "Ada", lastName: "Lovelace", secret: "  secret value  " }, "constructor copies data, trims names, and preserves secret whitespace");

const snap1 = manager.snapshot();
const snap2 = manager.snapshot();
assert(snap1 !== snap2, "snapshot returns a fresh object");
snap1.firstName = "Changed snapshot";
snap1.secret = "Changed snapshot";
equal(manager.snapshot(), { firstName: "Ada", lastName: "Lovelace", secret: "  secret value  " }, "snapshot mutation cannot alter state");

let update: UpdateResult = manager.rename("  Grace ", " Hopper  ");
equal(update, { ok: true, message: "Name updated" }, "successful rename result");
equal(manager.snapshot(), { firstName: "Grace", lastName: "Hopper", secret: "  secret value  " }, "rename trims and updates both names");

const beforeFailedRename = manager.snapshot();
update = manager.rename(" ", "Valid");
equal(update, { ok: false, message: "Both names are required" }, "empty first name rejected");
equal(manager.snapshot(), beforeFailedRename, "failed first-name rename does not mutate");
update = manager.rename("Valid", " ");
equal(update, { ok: false, message: "Both names are required" }, "empty last name rejected");
equal(manager.snapshot(), beforeFailedRename, "failed last-name rename does not mutate");

update = manager.changeSecret("wrong", "", "different");
equal(update, { ok: false, message: "Current secret is incorrect" }, "wrong current secret has highest precedence");
equal(manager.snapshot(), beforeFailedRename, "wrong current secret does not mutate");
update = manager.changeSecret("  secret value  ", "", "different");
equal(update, { ok: false, message: "New secret is required" }, "empty new secret precedes mismatch");
equal(manager.snapshot(), beforeFailedRename, "empty new secret does not mutate");
update = manager.changeSecret("  secret value  ", " new secret ", "new secret");
equal(update, { ok: false, message: "New secrets do not match" }, "repetition must match exactly");
equal(manager.snapshot(), beforeFailedRename, "mismatch does not mutate");
update = manager.changeSecret("  secret value  ", " new secret ", " new secret ");
equal(update, { ok: true, message: "Secret updated" }, "secret change succeeds");
assert(manager.snapshot().secret === " new secret ", "new secret whitespace is preserved exactly");

throwsType(() => new AccountManager({ firstName: " ", lastName: "Valid", secret: "x" }), "empty constructor first name");
throwsType(() => new AccountManager({ firstName: "Valid", lastName: " ", secret: "x" }), "empty constructor last name");
throwsType(() => new AccountManager({ firstName: "Valid", lastName: "Name", secret: " \t " }), "empty constructor secret");

const typedUpdate: AccountUpdate = { firstName: "A", lastName: "B" };
assert(typedUpdate.firstName === "A", "AccountUpdate export is usable");

